changeSet.sql:
UPDATE d SET highest_allocated_version = COALESCE(
    (SELECT MAX(v.version) FROM wf.workflow_definition_version v WHERE v.definition_id = d.id), 0)
    FROM wf.workflow_definition d;
ALTER TABLE wf.workflow_definition ADD CONSTRAINT ck_workflow_definition_highest_allocated_version
    CHECK (highest_allocated_version >= 0);
